    review: { keyVocab: ['za_enVirtud', 'za_aTenor', 'za_ahoraBien', 'za_habida', 'za_maxime', 'za_cierzo'], grammar: ['llevar + gerund (duration); seguir + gerund; venir + gerund (gradual).', 'venir a + inf. (approximately); llegar a + inf. (go as far as); acabar + gerund.', 'tener / quedar + participle (result, agreeing).', 'de ahí que + subjunctive; pese a (que); habida cuenta de que.', 'Concede → reserve (ahora bien / con todo) → argue.', 'Idioms: dar luz verde, estar en el aire, echar balones fuera, ir al grano.'], expressions: ['El presente documento tiene por objeto…', 'A tenor de…', 'Ahora bien,…', 'Es más,…', 'En suma,…'], mistakes: ['Trabajo aquí desde tres años → llevo tres años trabajando', 'asciende de → asciende a', 'de ahí que es → sea', 'dar la luz verde → dar luz verde'] },
