  MA.IDIOMS.zaragoza = [
    { es: 'Ser más terco que un aragonés', type: 'Expression', reg: 'Informal · humorous', lit: 'To be more stubborn than an Aragonese.', mean: 'To be extremely stubborn.', use: 'Joking stereotype; Aragonese people use it about themselves with pride.', not: 'Can sound like a stereotype; use with humour, among friends.', dlg: [['—No piensa cambiar de opinión.', '—He has no intention of changing his mind.'], ['—Claro, es más terco que un aragonés.', '—Of course, he’s as stubborn as they come.']], when: 'A colleague refuses to accept any other idea.' },
    { es: 'Marear la perdiz', type: 'Idiom', reg: 'Informal–neutral', lit: 'To make the partridge dizzy.', mean: 'To waste time, beat around the bush.', use: 'Meetings that go nowhere.', not: '', dlg: [['—Llevamos una hora hablando y nada.', '—We’ve been talking for an hour and nothing.'], ['—Están mareando la perdiz.', '—They’re just wasting time.']], when: 'A negotiation drags on with no decision.' },
    { es: 'Echar balones fuera', type: 'Idiom', reg: 'Neutral (press, politics)', lit: 'To kick balls out (of play).', mean: 'To dodge responsibility, deflect.', use: 'Common in political journalism.', not: '', dlg: [['—¿Qué dijo el ministro del error?', '—What did the minister say about the mistake?'], ['—Nada, echó balones fuera.', '—Nothing, he deflected.']], when: 'Someone blames others for their mistake.' },
    { es: 'Tener la sartén por el mango', type: 'Idiom', reg: 'Neutral', lit: 'To hold the frying pan by the handle.', mean: 'To be in control.', use: 'Power relations, negotiations.', not: '', dlg: [['—¿Quién decide?', '—Who decides?'], ['—El cliente: él tiene la sartén por el mango.', '—The client: he’s calling the shots.']], when: 'Describing who holds power in a deal.' },
    { es: 'Dar luz verde', type: 'Expression', reg: 'Neutral (press, business)', lit: 'To give green light.', mean: 'To approve, give the go-ahead.', use: 'Projects, laws, budgets.', not: 'No article: dar luz verde.', dlg: [['—¿Hay noticias del proyecto?', '—Any news on the project?'], ['—Sí, el ayuntamiento le ha dado luz verde.', '—Yes, the council has given it the go-ahead.']], when: 'Your proposal is approved.' },
    { es: 'Cada maestrillo tiene su librillo', type: 'Proverb', reg: 'Neutral', lit: 'Every little teacher has his little book.', mean: 'Everyone has their own way of doing things.', use: 'Accepting different methods.', not: '', dlg: [['—Yo lo habría hecho de otra forma.', '—I would have done it differently.'], ['—Ya, cada maestrillo tiene su librillo.', '—Sure, everyone has their own method.']], when: 'Two colleagues approach a task differently.' },
    { es: 'Al pan, pan, y al vino, vino', type: 'Proverb', reg: 'Neutral', lit: 'Call bread bread, and wine wine.', mean: 'To call a spade a spade; speak plainly.', use: 'Valuing directness — very Aragonese!', not: '', dlg: [['—¿Te digo la verdad?', '—Shall I tell you the truth?'], ['—Sí: al pan, pan, y al vino, vino.', '—Yes: call a spade a spade.']], when: 'You want brutally honest feedback.' },
    { es: 'Estar en el aire', type: 'Expression', reg: 'Neutral', lit: 'To be in the air.', mean: 'To be undecided, up in the air.', use: 'Plans, projects.', not: 'Not “on air” (= en antena / en directo).', dlg: [['—¿Se hace el congreso?', '—Is the conference going ahead?'], ['—Todavía está en el aire.', '—It’s still up in the air.']], when: 'Your internship start date is not confirmed.' }
  ];

  MA.STORIES.push({ id: 'amantesteruel', city: 'zaragoza', title: 'Los amantes de Teruel', en: 'The Lovers of Teruel (Aragonese legend)', level: 'C1', unlock: null,
    sentences: [['Cuenta la leyenda que, a comienzos del siglo XIII, vivían en Teruel dos jóvenes cuyo amor habría de hacerse célebre: Isabel de Segura y Diego de Marcilla.', 'Legend has it that, at the beginning of the 13th century, two young people lived in Teruel whose love was to become famous: Isabel de Segura and Diego de Marcilla.'], ['Ella pertenecía a una de las familias más acaudaladas de la ciudad, mientras que él, por ser segundón, apenas poseía fortuna.', 'She belonged to one of the wealthiest families in the city, whereas he, being a younger son, had hardly any fortune.'], ['El padre de Isabel, por mucho que apreciara al muchacho, se negó a concederle la mano de su hija sin que antes reuniera riquezas.', 'Isabel’s father, however much he may have liked the boy, refused to grant him his daughter’s hand unless he first gathered wealth.'], ['Diego le pidió un plazo de cinco años, transcurridos los cuales regresaría rico o renunciaría a ella para siempre.', 'Diego asked him for five years, after which he would return rich or give her up forever.'], ['Partió a la guerra y, tras incontables penalidades, logró amasar una considerable fortuna.', 'He went off to war and, after countless hardships, managed to amass a considerable fortune.'], ['Entretanto, cumplido el plazo sin noticias suyas, la familia de Isabel la obligó a casarse con otro hombre.', 'Meanwhile, the deadline having passed with no news of him, Isabel’s family forced her to marry another man.'], ['Fue el mismo día de la boda cuando Diego entró en Teruel, convencido de que llegaba a tiempo.', 'It was on the very day of the wedding that Diego entered Teruel, convinced he was arriving in time.'], ['Al enterarse de lo ocurrido, logró hablar con Isabel a solas y le suplicó un último beso.', 'On learning what had happened, he managed to speak to Isabel alone and begged her for one last kiss.'], ['Ella, fiel a su nuevo marido, se lo negó, lo cual, según la leyenda, bastó para que Diego cayera muerto a sus pies.', 'She, faithful to her new husband, refused, which, according to the legend, was enough for Diego to fall dead at her feet.'], ['Al día siguiente, durante el funeral, Isabel se acercó al cuerpo de su amado, lo besó y murió abrazada a él.', 'The next day, during the funeral, Isabel approached her beloved’s body, kissed him and died embracing him.'], ['Conmovidas, ambas familias decidieron enterrarlos juntos.', 'Moved, both families decided to bury them together.'], ['Hoy sus restos reposan en un mausoleo de Teruel, donde dos esculturas de alabastro los muestran con las manos casi tocándose.', 'Today their remains rest in a mausoleum in Teruel, where two alabaster sculptures show them with their hands almost touching.']],
    phrases: { 'cuenta la leyenda que': { en: 'legend has it that', pos: 'fixed expression' }, 'cuyo amor': { en: 'whose love', ctx: 'cuyo agrees with «amor» (m sg).', pos: 'relative' }, 'habría de hacerse célebre': { en: 'was to become famous', ctx: 'haber de + infinitive in the conditional = future-in-the-past destiny (literary).', pos: 'periphrasis' }, 'mientras que': { en: 'whereas', pos: 'connector' }, 'por ser segundón': { en: 'being a younger son', ctx: 'por + infinitive = because of being.', pos: 'structure' }, 'por mucho que apreciara': { en: 'however much he may have liked', ctx: 'Concessive + imperfect subjunctive (past).', pos: 'structure' }, 'sin que antes reuniera': { en: 'unless he first gathered', ctx: 'sin que + imperfect subjunctive.', pos: 'structure' }, 'transcurridos los cuales': { en: 'after which (had passed)', ctx: 'Absolute participle + relative «los cuales».', pos: 'structure' }, 'tras incontables penalidades': { en: 'after countless hardships', pos: 'expression' }, 'cumplido el plazo': { en: 'the deadline having passed', ctx: 'Absolute participle construction (literary).', pos: 'structure' }, 'fue el mismo día de la boda cuando': { en: 'it was on the very day of the wedding that', ctx: 'Cleft sentence of time.', pos: 'cleft' }, 'al enterarse de lo ocurrido': { en: 'on learning what had happened', ctx: 'al + infinitive = when/on doing.', pos: 'structure' }, 'lo cual': { en: 'which (whole idea)', pos: 'relative' }, 'bastó para que cayera': { en: 'was enough for him to fall', ctx: 'bastar para que + imperfect subjunctive.', pos: 'structure' } },
    gloss: { 'leyenda': { en: 'legend', pos: 'noun' }, 'comienzos': { en: 'beginnings', pos: 'noun' }, 'célebre': { en: 'famous', pos: 'adjective' }, 'pertenecía': { en: 'belonged', pos: 'verb' }, 'acaudaladas': { en: 'wealthy', pos: 'adjective' }, 'segundón': { en: 'younger son (no inheritance)', pos: 'noun' }, 'apenas': { en: 'hardly', pos: 'adverb' }, 'poseía': { en: 'possessed', pos: 'verb' }, 'concederle': { en: 'to grant him', pos: 'verb' }, 'riquezas': { en: 'riches', pos: 'noun' }, 'plazo': { en: 'term, deadline', pos: 'noun' }, 'renunciaría': { en: 'would give up', pos: 'verb' }, 'partió': { en: 'set off', pos: 'verb' }, 'guerra': { en: 'war', pos: 'noun' }, 'amasar': { en: 'to amass', pos: 'verb' }, 'considerable': { en: 'considerable', pos: 'adjective' }, 'entretanto': { en: 'meanwhile', pos: 'adverb' }, 'obligó': { en: 'forced', pos: 'verb' }, 'convencido': { en: 'convinced', pos: 'adjective' }, 'suplicó': { en: 'begged', pos: 'verb' }, 'fiel': { en: 'faithful', pos: 'adjective' }, 'muerto': { en: 'dead', pos: 'adjective' }, 'funeral': { en: 'funeral', pos: 'noun' }, 'amado': { en: 'beloved', pos: 'noun' }, 'abrazada': { en: 'embracing', pos: 'participle' }, 'conmovidas': { en: 'moved (emotionally)', pos: 'participle' }, 'enterrarlos': { en: 'to bury them', pos: 'verb' }, 'restos': { en: 'remains', pos: 'noun' }, 'reposan': { en: 'rest', pos: 'verb' }, 'mausoleo': { en: 'mausoleum', pos: 'noun' }, 'esculturas': { en: 'sculptures', pos: 'noun' }, 'alabastro': { en: 'alabaster', pos: 'noun' } },
    quiz: [{ q: 'Why did Isabel’s father refuse at first?', o: ['Diego was from Zaragoza', 'Diego had no fortune', 'Isabel didn’t love him'], a: 1 }, { q: 'How long did Diego ask for?', o: ['Three years', 'Five years', 'Ten years'], a: 1 }, { q: '«Fue el mismo día de la boda cuando…» is…', o: ['a cleft sentence highlighting time', 'a conditional', 'reported speech'], a: 0 }, { q: '«cumplido el plazo» means…', o: ['the deadline having passed', 'to complete a deadline', 'the deadline will pass'], a: 0 }] });

  MA.READINGS.push(
    { id: 'zaragoza-1', city: 'zaragoza', title: 'El cierzo: enemigo y aliado', en: 'The cierzo: enemy and ally', type: 'Feature article (C1)', level: 'C1',
      sentences: [['Pocos fenómenos definen tanto el carácter de una ciudad como el cierzo define el de Zaragoza.', 'Few phenomena define a city’s character as much as the cierzo defines Zaragoza’s.'], ['Este viento del noroeste, que puede superar los cien kilómetros por hora, viene siendo objeto de quejas desde tiempos de los romanos.', 'This north-westerly wind, which can exceed a hundred kilometres per hour, has been the subject of complaints since Roman times.'], ['Ahora bien, lo que antaño se consideraba una maldición se ha convertido en una fuente de riqueza.', 'That said, what was once considered a curse has become a source of wealth.'], ['Habida cuenta de su intensidad y constancia, Aragón alberga hoy algunos de los parques eólicos más productivos de Europa.', 'Given its intensity and constancy, Aragón today hosts some of the most productive wind farms in Europe.'], ['Con todo, no faltan voces que alertan del impacto paisajístico y de la escasa repercusión económica en los pueblos afectados.', 'Even so, there is no shortage of voices warning about the landscape impact and the limited economic benefit for the affected villages.'], ['Sea como fuere, los zaragozanos siguen sujetándose el sombrero y bromeando: «Si no hace cierzo, no es Zaragoza».', 'Be that as it may, Zaragozans keep holding on to their hats and joking: “If there’s no cierzo, it isn’t Zaragoza.”']],
      phrases: { 'pocos fenómenos definen tanto': { en: 'few phenomena define as much', pos: 'structure' }, 'viene siendo objeto de': { en: 'has been the subject of', ctx: 'venir + gerund (ongoing from the past).', pos: 'periphrasis' }, 'ahora bien': { en: 'that said', pos: 'connector' }, 'antaño': { en: 'formerly, in days gone by', pos: 'adverb (literary)' }, 'habida cuenta de': { en: 'given', pos: 'connector' }, 'alberga': { en: 'hosts, houses', pos: 'verb' }, 'con todo': { en: 'even so', pos: 'connector' }, 'no faltan voces que alertan': { en: 'there is no shortage of voices warning', pos: 'expression' }, 'sea como fuere': { en: 'be that as it may', ctx: 'Fossilised future subjunctive (fuere).', pos: 'fixed expression' }, 'sujetándose el sombrero': { en: 'holding on to their hats', pos: 'expression' } },
      quiz: [{ q: 'How has the view of the cierzo changed?', o: ['From curse to source of wealth', 'From useful to dangerous', 'It hasn’t changed'], a: 0 }, { q: 'What concerns do critics raise?', o: ['Noise only', 'Landscape impact and little local benefit', 'Wind is too weak'], a: 1 }, { q: '«Sea como fuere» means…', o: ['Whatever it was', 'Be that as it may', 'If it were so'], a: 1 }] },
    { id: 'zaragoza-2', city: 'zaragoza', title: 'Goya, el aragonés universal', en: 'Goya, the universal Aragonese', type: 'Biographical essay', level: 'C1',
      sentences: [['Francisco de Goya nació en 1746 en Fuendetodos, un pequeño pueblo aragonés cuya casa natal todavía puede visitarse.', 'Francisco de Goya was born in 1746 in Fuendetodos, a small Aragonese village whose birthplace can still be visited.'], ['Fue en Zaragoza donde se formó como pintor y donde realizó algunos de sus primeros frescos, en la basílica del Pilar.', 'It was in Zaragoza that he trained as a painter and where he made some of his first frescoes, in the Pilar basilica.'], ['Tras llegar a ser pintor de la corte, presenció la invasión napoleónica, lo cual marcó profundamente su obra.', 'After rising to become court painter, he witnessed the Napoleonic invasion, which deeply marked his work.'], ['Los grabados de «Los desastres de la guerra» muestran una crudeza que, por mucho que hayan pasado dos siglos, sigue estremeciendo al espectador.', 'The prints of “The Disasters of War” show a rawness that, however much two centuries have passed, still makes viewers shudder.'], ['En sus últimos años, sordo y desencantado, pintó en las paredes de su casa las llamadas «Pinturas negras».', 'In his final years, deaf and disillusioned, he painted the so-called “Black Paintings” on the walls of his house.'], ['No sería exagerado afirmar que Goya anticipó buena parte del arte moderno.', 'It would not be an exaggeration to say that Goya anticipated much of modern art.']],
      phrases: { 'cuya casa natal': { en: 'whose birthplace', pos: 'relative' }, 'fue en zaragoza donde': { en: 'it was in Zaragoza that', ctx: 'Cleft sentence of place.', pos: 'cleft' }, 'llegar a ser': { en: 'to rise to become', ctx: 'llegar a + infinitive.', pos: 'periphrasis' }, 'presenció': { en: 'witnessed', pos: 'verb' }, 'lo cual marcó': { en: 'which marked', pos: 'relative' }, 'por mucho que hayan pasado': { en: 'however much has passed', ctx: 'Concessive + perfect subjunctive.', pos: 'structure' }, 'sigue estremeciendo': { en: 'still makes (people) shudder', ctx: 'seguir + gerund.', pos: 'periphrasis' }, 'las llamadas': { en: 'the so-called', pos: 'expression' }, 'no sería exagerado afirmar que': { en: 'it would not be an exaggeration to say that', ctx: 'Hedged academic claim.', pos: 'expression' } },
      quiz: [{ q: 'Where did Goya train as a painter?', o: ['Madrid', 'Zaragoza', 'Fuendetodos'], a: 1 }, { q: 'What marked his work deeply?', o: ['The Napoleonic invasion', 'A trip to Italy', 'His wedding'], a: 0 }, { q: 'Where did he paint the Black Paintings?', o: ['In the Pilar basilica', 'On the walls of his house', 'In the royal palace'], a: 1 }] }
  );
  Object.assign(MA.READ_GLOSS, { 'fenómenos': { en: 'phenomena', pos: 'noun' }, 'carácter': { en: 'character', pos: 'noun' }, 'noroeste': { en: 'north-west', pos: 'noun' }, 'superar': { en: 'to exceed', pos: 'verb' }, 'quejas': { en: 'complaints', pos: 'noun' }, 'romanos': { en: 'Romans', pos: 'noun' }, 'maldición': { en: 'curse', pos: 'noun' }, 'fuente': { en: 'source', pos: 'noun' }, 'riqueza': { en: 'wealth', pos: 'noun' }, 'intensidad': { en: 'intensity', pos: 'noun' }, 'constancia': { en: 'constancy', pos: 'noun' }, 'parques': { en: 'parks; farms (wind)', pos: 'noun' }, 'eólicos': { en: 'wind (adj.)', pos: 'adjective' }, 'productivos': { en: 'productive', pos: 'adjective' }, 'paisajístico': { en: 'landscape (adj.)', pos: 'adjective' }, 'escasa': { en: 'scarce, limited', pos: 'adjective' }, 'repercusión': { en: 'impact', pos: 'noun' }, 'afectados': { en: 'affected', pos: 'participle' }, 'zaragozanos': { en: 'people of Zaragoza', pos: 'noun' }, 'bromeando': { en: 'joking', pos: 'gerund' }, 'pueblo': { en: 'village', pos: 'noun' }, 'natal': { en: 'native, of birth', pos: 'adjective' }, 'formó': { en: 'trained', pos: 'verb' }, 'frescos': { en: 'frescoes', pos: 'noun' }, 'basílica': { en: 'basilica', pos: 'noun' }, 'corte': { en: 'court', pos: 'noun' }, 'invasión': { en: 'invasion', pos: 'noun' }, 'napoleónica': { en: 'Napoleonic', pos: 'adjective' }, 'profundamente': { en: 'deeply', pos: 'adverb' }, 'grabados': { en: 'prints, engravings', pos: 'noun' }, 'desastres': { en: 'disasters', pos: 'noun' }, 'crudeza': { en: 'rawness, harshness', pos: 'noun' }, 'espectador': { en: 'viewer', pos: 'noun' }, 'sordo': { en: 'deaf', pos: 'adjective' }, 'desencantado': { en: 'disillusioned', pos: 'adjective' }, 'paredes': { en: 'walls', pos: 'noun' }, 'exagerado': { en: 'exaggerated', pos: 'adjective' }, 'anticipó': { en: 'anticipated', pos: 'verb' } });

  MA.RADIO.push({ id: 'r8', city: 'zaragoza', title: 'Aula Abierta: ¿Atención en peligro?', en: 'Open Lecture: Is attention in danger?', level: 'C1', type: 'University radio panel', unlock: null,
    desc: 'Ana Lacasa moderates a university radio panel with a neuroscientist and a tech entrepreneur about technology and attention.',
    lines: [['A', 'Buenas tardes y bienvenidos a «Aula Abierta». Hoy nos preguntamos si la tecnología está erosionando nuestra capacidad de atención.', 'Good afternoon and welcome to “Open Lecture”. Today we ask whether technology is eroding our capacity for attention.'], ['A', 'Nos acompañan la neurocientífica Elena Royo y el emprendedor Pablo Gimeno. Doctora, usted primero.', 'With us are neuroscientist Elena Royo and entrepreneur Pablo Gimeno. Doctor, you first.'], ['E', 'Gracias. Los datos parecen indicar que la atención sostenida viene disminuyendo, sobre todo entre los más jóvenes.', 'Thank you. The data seem to indicate that sustained attention has been declining, especially among the youngest.'], ['E', 'Ahora bien, cabe matizar que no es la tecnología en sí, sino el diseño de ciertas aplicaciones, lo que fomenta la distracción.', 'That said, it should be qualified that it is not technology itself but the design of certain apps that encourages distraction.'], ['P', 'Coincido en parte. Con todo, no conviene demonizar las pantallas: también han democratizado el acceso al conocimiento.', 'I partly agree. Even so, we shouldn’t demonise screens: they have also democratised access to knowledge.'], ['E', 'Nadie lo niega. Es más, yo misma uso aplicaciones para investigar. Lo que propongo es un diseño más ético.', 'Nobody denies that. What’s more, I use apps myself for research. What I propose is more ethical design.'], ['P', 'Ahí estamos de acuerdo, siempre que la regulación no frene la innovación.', 'There we agree, provided regulation doesn’t hold back innovation.'], ['A', 'En suma: ni apocalípticos ni ingenuos. Gracias a ambos por un debate tan matizado.', 'In sum: neither apocalyptic nor naïve. Thank you both for such a nuanced debate.']],
    voices: { A: 'rounded', E: 'airy', P: 'glassy' }, names: { A: 'Ana', E: 'Elena', P: 'Pablo' },
    quiz: [{ q: 'According to Dr Royo, what causes distraction?', o: ['Technology itself', 'The design of certain apps', 'Young people'], a: 1 }, { q: 'What positive point does Pablo make?', o: ['Screens democratised access to knowledge', 'Screens improve attention', 'Apps should be banned'], a: 0 }, { q: 'Where do they agree?', o: ['On banning phones', 'On more ethical design, if regulation doesn’t stop innovation', 'They never agree'], a: 1 }, { q: '«ni apocalípticos ni ingenuos» means…', o: ['neither doom-mongers nor naïve', 'both pessimistic and naïve', 'apocalyptic but realistic'], a: 0 }],
    dictation: ['Cabe matizar que no es la tecnología en sí.', 'Siempre que la regulación no frene la innovación.'] });

  const A = MA.MENTORS.zaragoza; const m = (es, en) => ({ m: es, en });
  A.chapters = {
    za1: [m('Bienvenida al nivel avanzado. Aquí ya no buscamos frases correctas, sino frases precisas.', 'Welcome to the advanced level. Here we no longer look for correct sentences, but precise ones.'), m('Cada matiz cuenta. Y le advierto: soy exigente. Al pan, pan, y al vino, vino.', 'Every nuance counts. And I warn you: I’m demanding. I call a spade a spade.'), { choose: [{ es: 'Me parece perfecto.', en: 'That suits me perfectly.', re: m('Así me gusta. Empezamos con el subjuntivo que piensa.', 'That’s what I like. We start with the subjunctive that thinks.') }, { es: 'Me da un poco de respeto…', en: 'It’s a bit intimidating…', re: m('Es lógico que le imponga. Por mucho que cueste al principio, verá resultados.', 'It’s natural it intimidates you. However hard it is at first, you’ll see results.') }] }],
    za2: [m('Ahora, español profesional: propuestas, informes y reuniones donde nadie marea la perdiz.', 'Now, professional Spanish: proposals, reports and meetings where nobody beats around the bush.'), m('Le prepararé como si mañana presentara un proyecto en el ayuntamiento.', 'I will prepare you as if you were presenting a project at the city council tomorrow.')]
  };
  A.tips = {
    za1l1: [m('Aunque es = lo afirmo. Aunque sea = no lo discuto o no lo sé.', 'Aunque es = I assert it. Aunque sea = I don’t argue it or don’t know.'), m('«Por mucho que» siempre lleva subjuntivo.', '“Por mucho que” always takes the subjunctive.')],
    za1l2: [m('En español la preposición nunca se queda al final: la empresa en la que trabajo.', 'In Spanish the preposition never goes at the end: la empresa en la que trabajo.'), m('«Cuyo» concuerda con lo poseído: el autor cuyas novelas.', '“Cuyo” agrees with what is owned: el autor cuyas novelas.')],
    za1l3: [m('Prohibido «cosa» y «un montón» en un texto académico.', '“Cosa” and “un montón” are banned in academic writing.'), m('Atenúe: «los datos parecen indicar» es más sólido que «es obvio».', 'Hedge: “los datos parecen indicar” is stronger than “es obvio”.')],
    za2l1: [m('Llevo, sigo, vengo, acabo… las perífrasis dan precisión temporal.', 'Llevo, sigo, vengo, acabo… periphrases give time precision.'), m('El coste asciende A, no DE.', 'The cost amounts TO (a), not OF (de).')],
    za2l2: [m('Conceda, matice y argumente: es cierto que…; ahora bien…', 'Concede, qualify and argue: es cierto que…; ahora bien…'), m('«De ahí que» exige subjuntivo.', '“De ahí que” requires the subjunctive.')],
    za2l3: [m('Reconozca los modismos, pero en un informe use su equivalente formal.', 'Recognise idioms, but in a report use the formal equivalent.'), m('Si oye «ahora bien», prepárese: viene la objeción.', 'If you hear “ahora bien”, get ready: the objection is coming.')]
  };
  MA.CITY.zaragoza.built = true;
  MA.CITY.zaragoza.topics = [['Nuanced grammar (subjunctive with nuance)', 'za1l1'], ['Advanced sentence structures', 'za1l2'], ['Academic vocabulary & register', 'za1l3'], ['Formal communication & periphrases', 'za2l1'], ['Argumentative writing', 'za2l2'], ['Professional Spanish', 'za2l1'], ['Advanced idioms', 'za2l3'], ['Complex listening comprehension', 'za2l3']];
